package server

import (
	"bufio"
	"log/slog"
	"net/http"
	"os"
	"strings"
	"testing"

	"github.com/go-chi/chi/v5"

	"github.com/kynto/capsule/backend/internal/config"
)

// Every route the router really mounts must have a row in internal/authz/routes_authz.golden (the table of
// what each route requires today, generated by tools/routeperms). The generator reads the source, so it also
// covers the routes mounted only when an optional dependency is configured; this test is the independent
// check on the live router that the generator did not miss anything. When it fails, run
// `go run ./tools/routeperms` from the backend directory and classify the new route in
// tools/routeperms/classes.go if it is not decided by authz.
func TestEveryMountedRouteHasAGoldenRow(t *testing.T) {
	f, err := os.Open("../authz/routes_authz.golden")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	golden := map[string]bool{} // "METHOD path"; ANY rows are expanded below
	any := map[string]bool{}
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		if strings.HasPrefix(line, "#") || line == "" {
			continue
		}
		c := strings.Split(line, "\t")
		if len(c) != 6 {
			t.Fatalf("malformed golden row: %q", line)
		}
		if c[0] == "ANY" {
			any[c[1]] = true
		} else {
			golden[c[0]+" "+c[1]] = true
		}
	}

	r := newRouter(&config.Config{}, slog.Default(), "test", Deps{})
	mounted := 0
	_ = chi.Walk(r, func(method, route string, _ http.Handler, _ ...func(http.Handler) http.Handler) error {
		mounted++
		if !golden[method+" "+route] && !any[route] {
			t.Errorf("mounted route without a golden row: %s %s", method, route)
		}
		return nil
	})
	if mounted < 200 {
		t.Fatalf("only %d routes mounted; the router changed shape", mounted)
	}
	t.Logf("%d mounted route/method pairs checked against %d golden rows", mounted, len(golden)+len(any))
}
